'use client';

import { useEffect, useId, useLayoutEffect, useRef, useState, type ReactNode, type KeyboardEvent } from 'react';
import { motion, useReducedMotion } from 'motion/react';
import './segmented-control.css';
import './reading-tabs.css';

export type ReadingTab = {
  /** Stable application key. Unique within this ReadingTabs instance. */
  value: string;
  label: string;
  icon?: ReactNode;
  count?: number;
  badge?: string;
  disabled?: boolean;
  /** Invoked only when content is mounted. Return content, not another tabpanel. */
  render: () => ReactNode;
};

export type ReadingTabsProps = {
  tabs: ReadingTab[];
  label: string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Manual is the default for expensive reading panels. */
  activationMode?: 'manual' | 'automatic';
  /** Retain visited content, including local editor/scroll state. Never mounts unvisited content. */
  keepMounted?: boolean;
  variant?: 'buttons' | 'tray' | 'underline';
  size?: 'sm' | 'md' | 'lg';
  appearance?: 'clean' | 'classic';
  className?: string;
};

/** Owns both tabs and panel shells. Uses SegmentedControl CSS, never its radio/keyboard renderer. */
export function ReadingTabs({ tabs, label, value, defaultValue, onValueChange,
  activationMode = 'manual', keepMounted = false, variant = 'buttons', size = 'md',
  appearance = 'clean', className = '' }: ReadingTabsProps) {
  const id = useId();
  const [localValue, setLocalValue] = useState(defaultValue ?? tabs.find(tab => !tab.disabled)?.value);
  const requested = value ?? localValue;
  const selected = tabs.find(tab => tab.value === requested && !tab.disabled)?.value;
  const [focused, setFocused] = useState<string | undefined>();
  const [visited, setVisited] = useState<Set<string>>(() => new Set(selected === undefined ? [] : [selected]));
  const listRef = useRef<HTMLDivElement>(null);
  const scrollerRef = useRef<HTMLDivElement>(null);
  const indicatorRef = useRef<HTMLSpanElement>(null);
  const [geometry, setGeometry] = useState<{ left: number; right: number; direction: number } | null>(null);
  const reduced = useReducedMotion();
  const enabled = tabs.filter(tab => !tab.disabled);
  const tabStop = enabled.find(tab => tab.value === focused)?.value ?? selected ?? enabled[0]?.value;
  const tabId = (key: string) => `${id}-tab-${encodeURIComponent(key)}`;
  const panelId = (key: string) => `${id}-panel-${encodeURIComponent(key)}`;

  useEffect(() => {
    if (selected !== undefined) setVisited(current => current.has(selected) ? current : new Set([...current, selected]));
  }, [selected]);

  useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;
    function measure() {
      const active = Array.from(list!.querySelectorAll<HTMLButtonElement>('[role="tab"]')).find(tab => tab.dataset.value === selected);
      if (!active) { setGeometry(null); return; }
      const inset = variant === 'underline' ? 2 : 0;
      const left = active.offsetLeft + inset;
      // Both edges use the track's left origin. A changing track width must not
      // move the pill's right edge before its animation has started.
      const right = active.offsetLeft + active.offsetWidth - inset;
      const renderedLeft = indicatorRef.current?.offsetLeft ?? left;
      const direction = Math.sign(left - renderedLeft);
      setGeometry(current => current?.left === left && current.right === right ? current : { left, right, direction });
    }
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(list);
    list.querySelectorAll('[role="tab"]').forEach(tab => observer.observe(tab));
    return () => observer.disconnect();
  }, [selected, tabs, variant, size, appearance]);

  function reveal(button: HTMLButtonElement) {
    const scroller = scrollerRef.current;
    const list = listRef.current;
    if (!scroller || !list) return;
    const start = list.offsetLeft + button.offsetLeft;
    const end = start + button.offsetWidth;
    if (start < scroller.scrollLeft) scroller.scrollLeft = start;
    else if (end > scroller.scrollLeft + scroller.clientWidth) scroller.scrollLeft = end - scroller.clientWidth;
  }
  useLayoutEffect(() => {
    const button = Array.from(listRef.current?.querySelectorAll<HTMLButtonElement>('[role="tab"]') ?? []).find(tab => tab.dataset.value === selected);
    if (button) reveal(button);
  }, [selected]);

  function activate(next: string) {
    if (next === selected || !enabled.some(tab => tab.value === next)) return;
    if (value === undefined) setLocalValue(next);
    onValueChange?.(next);
  }
  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const button = (event.target as HTMLElement).closest<HTMLButtonElement>('[role="tab"]');
    if (!button || !enabled.length) return;
    const index = enabled.findIndex(tab => tab.value === button.dataset.value);
    const target = event.key === 'Home' ? 0 : event.key === 'End' ? enabled.length - 1
      : event.key === 'ArrowLeft' ? (index - 1 + enabled.length) % enabled.length
      : event.key === 'ArrowRight' ? (index + 1) % enabled.length : undefined;
    // Native buttons own Enter/Space. There is no second activation handler.
    if (target === undefined) return;
    event.preventDefault();
    const next = enabled[target].value;
    const nextButton = Array.from(listRef.current!.querySelectorAll<HTMLButtonElement>('[role="tab"]')).find(tab => tab.dataset.value === next)!;
    setFocused(next);
    nextButton.focus({ preventScroll: true });
    reveal(nextButton);
    if (activationMode === 'automatic') activate(next);
  }
  const timing = appearance === 'classic' ? { lead: .27, follow: .4, neutral: .38, ease: [.22, 1, .36, 1] as const }
    : { lead: .16, follow: .22, neutral: .2, ease: [.25, .9, .3, 1] as const };

  return <div className={`reading-tabs ${className}`} data-activation={activationMode}>
    <div className={`sc sc--${variant} sc--${size} sc--${appearance}`} data-reduced-motion={reduced || undefined}>
      <div className="sc-scroll" ref={scrollerRef}>
        <div className="sc-track" role="tablist" aria-label={label} aria-orientation="horizontal" ref={listRef} onKeyDown={onKeyDown}
          onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setFocused(undefined); }}>
          {geometry && <motion.span className="sc-indicator" ref={indicatorRef} aria-hidden="true" initial={false}
            style={{ left: 'var(--reading-left)', right: 'auto', width: 'calc(var(--reading-right) - var(--reading-left))' }}
            animate={{ '--reading-left': `${geometry.left}px`, '--reading-right': `${geometry.right}px` }} transition={{
              '--reading-left': { duration: reduced ? 0 : geometry.direction > 0 ? timing.follow : geometry.direction < 0 ? timing.lead : timing.neutral, ease: timing.ease },
              '--reading-right': { duration: reduced ? 0 : geometry.direction < 0 ? timing.follow : geometry.direction > 0 ? timing.lead : timing.neutral, ease: timing.ease },
            }}/>} 
          {tabs.map(tab => <button key={tab.value} type="button" role="tab" className="sc-option" id={tabId(tab.value)}
            data-value={tab.value} data-state={selected === tab.value ? 'checked' : 'unchecked'}
            aria-selected={selected === tab.value} aria-controls={panelId(tab.value)} disabled={tab.disabled}
            tabIndex={tab.value === tabStop ? 0 : -1} onFocus={event => { setFocused(tab.value); reveal(event.currentTarget); }} onClick={() => activate(tab.value)}>
            <span className="sc-content">
              {tab.icon && <span className="sc-icon" aria-hidden="true">{tab.icon}</span>}
              <span className="sc-label" data-label={tab.label}><span>{tab.label}</span><span className="sc-label-strong" aria-hidden="true">{tab.label}</span></span>
              {tab.count !== undefined && <span className="sc-count">{tab.count}</span>}
              {tab.badge && <span className="sc-badge">{tab.badge}</span>}
            </span>
          </button>)}
        </div>
      </div>
    </div>
    {tabs.map(tab => <div key={tab.value} role="tabpanel" className="reading-tabs__panel" id={panelId(tab.value)}
      aria-labelledby={tabId(tab.value)} hidden={selected !== tab.value} tabIndex={0}>
      {(selected === tab.value || (keepMounted && visited.has(tab.value))) ? tab.render() : null}
    </div>)}
  </div>;
}

/* Independent tab/panel renderer; segmented-control.css supplies the existing replica's visual skin. */
.reading-tabs { min-width: 0; }
.reading-tabs__panel { margin-top: 18px; min-width: 0; outline-offset: 4px; }
.reading-tabs__panel[hidden] { display: none; }
.reading-tabs__panel:focus-visible { outline: 2px solid #7c9ee9; border-radius: 4px; }
.reading-tabs .sc-option { overflow: visible; }

.sc {
  --sc-ink: rgb(0 0 0 / .88); --sc-muted: rgb(0 0 0 / .61);
  --sc-line: rgb(0 0 0 / .06); --sc-fill: rgb(0 0 0 / .06);
  --sc-tray: rgb(0 0 0 / .04); --sc-raised: #fff;
  --sc-badge: rgb(0 96 226 / .765); --sc-badge-fill: rgb(0 96 226 / .08);
  --sc-height: 28px; --sc-padding: 10px; --sc-font: 13px; --sc-line-height: 20px;
  --sc-width-duration: 200ms; --sc-width-ease: cubic-bezier(.25,.9,.3,1);
  display: block; width: max-content; max-width: 100%; min-width: 0;
  color: var(--sc-muted); font-family: inherit; font-size: var(--sc-font); font-weight: 500;
  line-height: var(--sc-line-height); border-radius: 8px;
}
:is([data-theme="dark"], .dark) .sc {
  --sc-ink: rgb(255 255 255 / .9); --sc-muted: rgb(255 255 255 / .62);
  --sc-line: rgb(255 255 255 / .08); --sc-fill: rgb(255 255 255 / .08);
  --sc-tray: rgb(255 255 255 / .05); --sc-raised: #2c2c2f;
  --sc-badge: #4d8dff; --sc-badge-fill: rgb(77 141 255 / .14);
}
.sc--sm { --sc-height: 24px; --sc-padding: 8px; --sc-font: 12px; --sc-line-height: 16px; }
.sc--lg { --sc-height: 32px; --sc-padding: 12px; --sc-font: 14px; }
.sc[data-full-width] { width: 100%; }
.sc--buttons.sc--clean[data-full-width] { width: calc(100% + 6px); }
.sc-scroll { position: relative; overflow-x: auto; scrollbar-width: none; border-radius: inherit; }
.sc-scroll::-webkit-scrollbar { display: none; }
.sc-scroll[data-fade-left] { mask-image: linear-gradient(to right,transparent,#000 16px); }
.sc-scroll[data-fade-right] { mask-image: linear-gradient(to left,transparent,#000 16px); }
.sc-scroll[data-fade-left][data-fade-right] { mask-image: linear-gradient(to right,transparent,#000 16px,#000 calc(100% - 16px),transparent); }
.sc-track { position: relative; display: flex; width: max-content; isolation: isolate; }
.sc-indicator { position: absolute; inset-block: 0; z-index: -1; background: var(--sc-fill); border-radius: 6px; pointer-events: none; }
.sc-option {
  appearance: none; position: relative; flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center;
  box-sizing: border-box; min-width: 0; overflow: hidden;
  height: var(--sc-height); margin: 0; padding: 0 var(--sc-padding); border: 0; border-radius: 6px;
  background: transparent; color: var(--sc-muted); font: inherit; white-space: nowrap; cursor: pointer;
  user-select: none; -webkit-user-select: none; touch-action: pan-x pan-y;
  transition: width var(--sc-width-duration) var(--sc-width-ease), color 90ms, background-color 90ms, scale 120ms cubic-bezier(.25,.9,.3,1);
}
.sc-option[data-state="checked"] { color: var(--sc-ink); }
.sc-option:hover:not(:disabled):not([data-state="checked"]) { background: var(--sc-tray); }
.sc-track:has(.sc-option:active:not(:disabled)) .sc-indicator { scale: .97; }
.sc-indicator { transition: scale 120ms cubic-bezier(.25,.9,.3,1); }
.sc--classic .sc-indicator { transition: scale 200ms cubic-bezier(.22,1,.36,1); }
.sc-label-strong { display: none; }
.sc-option:focus-visible { outline: 2px solid #7c9ee9; outline-offset: 1px; }
.sc-option:disabled { opacity: .4; cursor: default; }
.sc-content { display: inline-flex; flex-shrink: 0; align-items: center; justify-content: center; gap: 6px; }
.sc--sm .sc-content { gap: 5px; }
.sc-icon { width: 14px; height: 14px; display: inline-flex; color: rgb(0 0 0 / .447); transition: color 90ms; }
.sc-option[data-state="checked"] .sc-icon { color: var(--sc-ink); }
:is([data-theme="dark"], .dark) .sc-icon { color: rgb(255 255 255 / .46); }
.sc--classic .sc-icon { color: inherit; transition: none; }
:is([data-theme="dark"], .dark) .sc--classic .sc-icon { color: inherit; }
.sc-icon svg { width: 100%; height: 100%; }
.sc-count { display: inline-flex; align-items: center; justify-content: center; min-width: 16px; box-sizing: border-box; height: 16px; padding: 0 4px; border-radius: 5px; background: var(--sc-fill); font-size: 11px; line-height: 16px; font-variant-numeric: tabular-nums; }
.sc-badge { display: inline-flex; align-items: center; height: 18px; padding: 0 6px; border-radius: 5px; font-size: 11px; line-height: 16px; color: var(--sc-badge); background: var(--sc-badge-fill); }
.sc--buttons { margin: -3px; max-width: calc(100% + 6px); }
.sc--buttons .sc-scroll { padding: 3px; }
.sc--buttons .sc-track { gap: 8px; }
.sc--buttons .sc-option { box-shadow: inset 0 0 0 .5px var(--sc-line); }
.sc--tray { background: var(--sc-tray); }
.sc--tray .sc-scroll { padding: 2px; }
.sc--tray .sc-option { height: calc(var(--sc-height) - 4px); }
.sc--tray .sc-indicator { background: var(--sc-raised); box-shadow: 0 0 0 .5px var(--sc-line),0 1px 1px -1px rgb(0 0 0 / .1),0 1px 2px rgb(0 0 0 / .05); }
.sc--underline { border-radius: 0; box-shadow: inset 0 -.5px var(--sc-line); }
.sc--underline .sc-track { gap: 20px; }
.sc--underline .sc-option { height: calc(var(--sc-height) + 6px); padding-inline: 2px; }
.sc--underline .sc-indicator { top: auto; bottom: 0; height: 1.5px; border-radius: 1.5px 1.5px 0 0; background: var(--sc-ink); }
.sc--classic {
  --sc-height: 36px; --sc-padding: 12px; --sc-font: 13.5px; --sc-line-height: 13.5px;
  --sc-width-duration: 320ms; --sc-width-ease: cubic-bezier(.22,1,.36,1);
  --sc-ink: #171717; --sc-muted: #737373; --sc-tray: #f0f0f0;
  --sc-badge: #2f6bff; --sc-badge-fill: rgb(47 107 255 / .1);
  font-weight: 500; border-radius: 11px;
}
.sc--classic.sc--sm { --sc-height: 30px; --sc-padding: 10px; --sc-font: 12.5px; --sc-line-height: 12.5px; border-radius: 9px; }
.sc--classic.sc--lg { --sc-height: 42px; --sc-padding: 14px; --sc-font: 14.5px; --sc-line-height: 14.5px; }
.sc--classic.sc--buttons { margin: 0; max-width: 100%; background: var(--sc-tray); }
.sc--classic.sc--buttons .sc-track { gap: 0; }
.sc--classic.sc--buttons .sc-option { height: calc(var(--sc-height) - 6px); box-shadow: none; }
.sc--classic .sc-option { border-radius: 8px; transition: width var(--sc-width-duration) var(--sc-width-ease),color 200ms,scale 200ms cubic-bezier(.22,1,.36,1); }
.sc--classic .sc-label { display: grid; }
.sc--classic .sc-label>span { grid-area: 1 / 1; transition: opacity 200ms; }
.sc--classic .sc-label>span:first-child { font-weight: 500; opacity: 1; }
.sc--classic .sc-label>.sc-label-strong { display: block; font-weight: 600; opacity: 0; }
.sc--classic .sc-option[data-state="checked"] .sc-label>span:first-child { opacity: 0; }
.sc--classic .sc-option[data-state="checked"] .sc-label>.sc-label-strong { opacity: 1; }
.sc--classic .sc-content { gap: 6px; }
.sc--classic .sc-indicator { border-radius: 8px; background: var(--sc-raised); box-shadow: 0 0 0 .5px rgb(0 0 0 / .08),0 1px 2px rgb(0 0 0 / .08),0 2px 8px -2px rgb(0 0 0 / .06); }
.sc--classic.sc--sm .sc-option,.sc--classic.sc--sm .sc-indicator { border-radius: 7px; }
.sc--classic .sc-count { min-width: 18px; height: 18px; border-radius: 9px; padding: 0 5px; font-weight: 600; line-height: 11px; color: #404040; }
.sc--classic .sc-badge { border-radius: 6px; line-height: 11px; }
.sc--classic.sc--underline { border-radius: 0; box-shadow: inset 0 -1px #ececec; }
.sc--classic.sc--underline .sc-option { height: var(--sc-height); }
.sc--classic.sc--underline .sc-indicator { height: 2px; border-radius: 2px 2px 0 0; background: var(--sc-ink); box-shadow: none; }
:is([data-theme="dark"], .dark) .sc--tray .sc-indicator { box-shadow: 0 0 0 .5px rgb(255 255 255 / .1),0 1px 2px rgb(0 0 0 / .4); }
:is([data-theme="dark"], .dark) .sc--classic { --sc-ink: #ededed; --sc-muted: #8b8b92; --sc-tray: #111113; --sc-raised: #26262a; --sc-badge: #6d8bff; --sc-badge-fill: rgb(109 139 255 / .14); }
:is([data-theme="dark"], .dark) .sc--classic .sc-indicator { box-shadow: 0 0 0 1px rgb(255 255 255 / .06),0 1px 2px rgb(0 0 0 / .4); }
:is([data-theme="dark"], .dark) .sc--classic .sc-count { color: #c4c4c8; }
:is([data-theme="dark"], .dark) .sc--classic.sc--underline { box-shadow: inset 0 -1px #2a2a2e; }
:is([data-theme="dark"], .dark) .sc--classic.sc--underline .sc-indicator { box-shadow: none; }
@media (pointer: coarse) { .sc-option, .sc--tray .sc-option, .sc--underline .sc-option { min-height: 40px; } }
.sc[data-reduced-motion] .sc-option { transition: none; }
@media (prefers-reduced-motion: reduce) { .sc .sc-option { transition: none; } }

.sc[data-reduced-motion] :is(.sc-indicator,.sc-label>span) { transition: none; scale: none; }
@media (prefers-reduced-motion: reduce) { .sc :is(.sc-indicator,.sc-label>span) { transition: none; scale: none; } }
